nodes.implementation:
OPENQASM 3.1;
include "stdgates.inc";
qubit[2] encoded;
// Basis value 1 (little-endian: 01)
x encoded[0];
@leqo.output 0
let out = encoded;

OPENQASM 3.1;
include "stdgates.inc";
qubit[2] encoded;
// Basis value 3 (little-endian: 11)
x encoded[0];
x encoded[1];
@leqo.output 0
let out = encoded;

OPENQASM 3.1;
include "stdgates.inc";
@leqo.input 0
qubit[2] addend0;
@leqo.input 1
qubit[2] addend1;
qubit[3] sum;
qubit[1] carry;
ccx addend0[0], addend1[0], carry[0];
cx addend0[0], sum[0];
cx addend1[0], sum[0];
ccx addend0[1], addend1[1], sum[2];
ccx carry[0], addend0[1], sum[2];
ccx carry[0], addend1[1], sum[2];
cx addend0[1], sum[1];
cx addend1[1], sum[1];
cx carry[0], sum[1];
@leqo.output 0
let out = sum;

OPENQASM 3.1;
@leqo.input 0
qubit[3] q;
bit[3] result = measure q[{0, 1, 2}];
@leqo.output 0
let out = result;
@leqo.output 1
let qubit_out = q;
